typedef CGAL::Polygon_with_holes_2<Kernel> CGAL_Polygon_with_holes_2;

CGAL_Polygon_2 cgal_p1, cgal_p2;
for (const auto& point : P1.outer_boundary()) {
    cgal_p1.push_back(Point_2(point.x(), point.y()));
}
for (const auto& point : P2.outer_boundary()) {
    cgal_p2.push_back(Point_2(point.x(), point.y()));
}

// Compute intersection
std::list<CGAL_Polygon_with_holes_2> cgal_result;
CGAL::intersection(cgal_p1, cgal_p2, std::back_inserter(cgal_result));

// Convert CGAL result back to our format
for (const auto& cgal_poly : cgal_result) {
    PolygonWithHoles2d poly_with_holes;
    Polygon2d outer;
    for (const auto& point : cgal_poly.outer_boundary()) {
        outer.add_point(Point2d(point.x(), point.y()));
